//! 渲染：把解析+SSOT 解析后的 block 渲染成 Rust 契约测试，镜像现有手写测试模式。
//!
//! 镜像约束（来自 contracts/cli/contract-tests/README.md 与现有 13 个测试文件）：
//! - 自包含 `fn novel() -> Command { Command::cargo_bin("novel").unwrap() }`
//! - setup 调 fixtures/<name>.sh 建临时世界
//! - 断言逐字段 `actual["x"]` + `.code(N)`，不引入 jsonschema
//! - 文件头标 `// @generated by spec-gen. DO NOT EDIT.`

use crate::spec_parse::ParsedBlock;
use crate::ssot::{self, SsotMaps};
use std::path::Path;
use std::str::FromStr;

/// 解析后的 block（期望值已从 SSOT 解析为具体数值/字符串）。
#[derive(Debug, Clone)]
pub struct ResolvedBlock {
    pub spec_rel: String,
    pub domain: String,
    pub scenario_title: String,
    pub id: String,
    pub fixture: String,
    pub when: String,
    pub expects: Vec<Expect>,
}

/// 一条已解析的断言期望。
#[derive(Debug, Clone)]
pub enum Expect {
    Exit(i64),
    ErrorCode(String),
    JsonContains(Vec<String>),
    JsonField(String, String), // (field, value) 精确值
    EveryHas { item: String, field: String },
    OmittedHasReason(String),
    StdoutContains(String),
    JsonArrayLen(String, i64), // (field-path, expected array length)
    JsonNumField(String, i64), // (field-path, expected numeric value)
}

/// 从 serde_yaml::Value 取字符串值（去引号）。
fn yaml_str(v: &serde_yaml::Value) -> String {
    match v {
        serde_yaml::Value::String(s) => s.clone(),
        serde_yaml::Value::Number(n) => n.to_string(),
        other => serde_yaml::to_string(other).unwrap_or_default().trim().trim_matches('"').to_string(),
    }
}

/// 从 serde_yaml::Value 取字符串列表。
fn yaml_str_list(v: &serde_yaml::Value) -> anyhow::Result<Vec<String>> {
    let seq = v.as_sequence()
        .ok_or_else(|| anyhow::anyhow!("期望列表，得到 {:?}", v))?;
    Ok(seq.iter().map(yaml_str).collect())
}

/// 对一个 block 做期望解析：每条 assert 是单键 mapping，按键分发。
/// SSOT 对齐闸：outcome 查不到即 bail（非零退出，阻塞 cargo test）。
pub fn resolve_block(b: &ParsedBlock, maps: &SsotMaps) -> anyhow::Result<ResolvedBlock> {
    let mut expects = Vec::new();
    // 是否有显式 error_code 断言——有则不推 outcome 的通用错误码，避免细分码/通用码冲突。
    let has_explicit_code = b.block.assert.iter().any(|m| m.iter().any(|(k, _)| k.as_str() == Some("error_code")));
    for item in &b.block.assert {
        // 每项是单键 mapping：{key: value}
        let (key, value) = item.iter().next()
            .ok_or_else(|| anyhow::anyhow!("assert 项为空 mapping"))?;
        let key = key.as_str().unwrap_or_default();
        match key {
            "exit" => {
                let n: i64 = value.as_i64()
                    .or_else(|| value.as_str().and_then(|s| s.parse().ok()))
                    .ok_or_else(|| anyhow::anyhow!("exit 值非整数: {:?}", value))?;
                expects.push(Expect::Exit(n));
            }
            "outcome" => {
                let outcome = yaml_str(value);
                let exit = ssot::resolve_outcome_exit(maps, &outcome)?;
                expects.push(Expect::Exit(exit));
                // 无显式 error_code 时，补 outcome 的通用错误码；有显式码时让显式码主导。
                if !has_explicit_code {
                    if let Ok(code) = ssot::resolve_outcome_code(maps, &outcome) {
                        expects.push(Expect::ErrorCode(code));
                    }
                }
            }
            "error_code" => {
                let code = yaml_str(value);
                let exit = ssot::resolve_error_exit(maps, &code)?;
                expects.push(Expect::Exit(exit));
                expects.push(Expect::ErrorCode(code));
            }
            "json_contains" => {
                expects.push(Expect::JsonContains(yaml_str_list(value)?));
            }
            "json_field" => {
                // value 是 mapping {field: val}
                let inner = value.as_mapping()
                    .ok_or_else(|| anyhow::anyhow!("json_field 值应为 mapping: {:?}", value))?;
                let (f, v) = inner.iter().next()
                    .ok_or_else(|| anyhow::anyhow!("json_field mapping 为空"))?;
                expects.push(Expect::JsonField(yaml_str(f), yaml_str(v)));
            }
            "json_array_len" => {
                // value 是 mapping {字段: 期望长度}
                let inner = value.as_mapping()
                    .ok_or_else(|| anyhow::anyhow!("json_array_len 值应为 mapping: {:?}", value))?;
                let (f, v) = inner.iter().next()
                    .ok_or_else(|| anyhow::anyhow!("json_array_len mapping 为空"))?;
                let n: i64 = v.as_i64()
                    .or_else(|| v.as_str().and_then(|s| s.parse().ok()))
                    .ok_or_else(|| anyhow::anyhow!("json_array_len 期望长度非整数: {:?}", v))?;
                expects.push(Expect::JsonArrayLen(yaml_str(f), n));
            }
            "json_num_field" => {
                // value 是 mapping {字段: 期望数值}
                let inner = value.as_mapping()
                    .ok_or_else(|| anyhow::anyhow!("json_num_field 值应为 mapping: {:?}", value))?;
                let (f, v) = inner.iter().next()
                    .ok_or_else(|| anyhow::anyhow!("json_num_field mapping 为空"))?;
                let n: i64 = v.as_i64()
                    .or_else(|| v.as_str().and_then(|s| s.parse().ok()))
                    .ok_or_else(|| anyhow::anyhow!("json_num_field 期望值非整数: {:?}", v))?;
                expects.push(Expect::JsonNumField(yaml_str(f), n));
            }
            "omitted_has_reason" => {
                expects.push(Expect::OmittedHasReason(yaml_str(value)));
            }
            "stdout_contains" => {
                expects.push(Expect::StdoutContains(yaml_str(value)));
            }
            other if other.starts_with("every_") && other.ends_with("_has") => {
                // every_<item>_has: <field>
                let item_name = other.trim_start_matches("every_").trim_end_matches("_has").to_string();
                expects.push(Expect::EveryHas { item: item_name, field: yaml_str(value) });
            }
            other => {
                anyhow::bail!("未知 assert 键 '{other}'（spec-gen 需扩展分发表）");
            }
        }
    }
    // 去重 Exit（outcome/error_code 各推一次，保留首个）。
    let mut seen_exit = false;
    expects.retain(|e| match e {
        Expect::Exit(_) => { if seen_exit { false } else { seen_exit = true; true } }
        _ => true,
    });
    Ok(ResolvedBlock {
        spec_rel: b.spec_rel.clone(),
        domain: b.domain.clone(),
        scenario_title: b.scenario_title.clone(),
        id: b.block.id.clone(),
        fixture: b.block.fixture.clone(),
        when: b.block.when.clone(),
        expects,
    })
}

/// 按 domain 分组（一章一文件）。
pub fn group_by_domain(blocks: &[ResolvedBlock]) -> Vec<(String, Vec<ResolvedBlock>)> {
    let mut groups: Vec<(String, Vec<ResolvedBlock>)> = Vec::new();
    for b in blocks {
        if let Some(g) = groups.iter_mut().find(|(d, _)| d == &b.domain) {
            g.1.push(b.clone());
        } else {
            groups.push((b.domain.clone(), vec![b.clone()]));
        }
    }
    groups
}

/// 渲染一个 domain 的生成测试文件内容（不写盘）。
pub fn render_test_content(domain: &str, blocks: &[ResolvedBlock]) -> String {
    let mut code = String::new();
    code.push_str("// @generated by spec-gen. DO NOT EDIT.\n");
    code.push_str("// 运行 `cargo run -p spec-gen -- generate` 重新生成。修改源 openspec/specs/ 的 @codegen 块。\n");
    code.push_str(&format!("// source: openspec/specs/{}/spec.md\n\n", domain));
    code.push_str("// 生成式契约测试：从 spec @codegen 块生成，构造性消除设计↔实现漂移。\n");
    code.push_str("// 镜像手写契约测试模式（assert_cmd 子进程 + tempdir + 逐字段断言）。\n\n");
    code.push_str("use assert_cmd::Command;\n");
    code.push_str("use predicates::prelude::*;\n");
    code.push_str("use serde_json::Value;\n");
    code.push_str("use tempfile::tempdir;\n\n");
    code.push_str("fn novel() -> Command {\n    Command::cargo_bin(\"novel\").unwrap()\n}\n\n");
    code.push_str("/// 用 fixture 脚本建临时世界，返回世界目录。\n");
    code.push_str("/// fixture 脚本经 NOVEL_BIN 调 novel；脚本路径从 CARGO_MANIFEST_DIR 解析到仓库根。\n");
    code.push_str("fn setup_fixture(fixture: &str) -> tempfile::TempDir {\n");
    code.push_str("    let dir = tempdir().unwrap();\n");
    code.push_str("    let novel_bin = assert_cmd::cargo::cargo_bin(\"novel\");\n");
    code.push_str("    // CARGO_MANIFEST_DIR = crates/novel-cli，仓库根 = 其上两级。\n");
    code.push_str("    let manifest = env!(\"CARGO_MANIFEST_DIR\");\n");
    code.push_str("    let repo_root = std::path::Path::new(manifest)\n");
    code.push_str("        .parent().and_then(|p| p.parent())\n");
    code.push_str("        .expect(\"无法从 CARGO_MANIFEST_DIR 解析仓库根\");\n");
    code.push_str("    let script = repo_root.join(format!(\"contracts/cli/fixtures/{fixture}.sh\"));\n");
    code.push_str("    let status = std::process::Command::new(\"bash\")\n");
    code.push_str("        .arg(&script)\n");
    code.push_str("        .arg(dir.path())\n");
    code.push_str("        .env(\"NOVEL_BIN\", &novel_bin)\n");
    code.push_str("        .status()\n");
    code.push_str("        .expect(\"fixture 脚本启动失败\");\n");
    code.push_str("    assert!(status.success(), \"fixture {fixture} 执行失败: {status}\\n  script: {}\", script.display());\n");
    code.push_str("    dir\n}\n\n");
    for b in blocks {
        code.push_str(&render_one_test(b));
        code.push_str("\n\n");
    }
    code
}

/// 渲染一个 domain 的生成测试文件（写盘）。
pub fn render_test_file(
    domain: &str,
    blocks: &[ResolvedBlock],
    out_path: &Path,
) -> anyhow::Result<()> {
    let code = render_test_content(domain, blocks);
    if let Some(parent) = out_path.parent() {
        std::fs::create_dir_all(parent)?;
    }
    std::fs::write(out_path, code)?;
    Ok(())
}

/// 把点号路径渲染为 actual 索引链：`budget.limit` → `actual["budget"]["limit"]`。
fn render_json_index(field: &str) -> String {
    let mut s = String::from("actual");
    for part in field.split('.') {
        s.push_str(&format!("[\"{}\"]", part));
    }
    s
}

/// 渲染单个 #[test] 函数。
fn render_one_test(b: &ResolvedBlock) -> String {
    let mut s = String::new();
    s.push_str(&format!("/// spec scenario: {}\n", b.scenario_title));
    s.push_str(&format!("/// source: {}\n", b.spec_rel));
    s.push_str("#[test]\n");
    s.push_str(&format!("fn {}() {{\n", b.id));
    s.push_str(&format!("    let dir = setup_fixture(\"{}\");\n", b.fixture));

    // 解析 when 命令为 args（去掉开头 novel 二进制名，cargo_bin("novel") 已提供）。
    let args = shell_split(&b.when);
    let args: Vec<String> = args.into_iter()
        .skip_while(|a| a == "novel")
        .collect();
    s.push_str("    let out = novel()\n");
    s.push_str("        .args([");
    let mut first = true;
    for a in &args {
        if !first { s.push_str(", "); }
        first = false;
        s.push_str(&format!("\"{}\"", a.replace('\\', "\\\\").replace('"', "\\\"")));
    }
    s.push_str("])\n");
    s.push_str("        .arg(\"--path\").arg(dir.path())\n");

    // 退出码：若有 Exit 期望，断 .code(N)；否则 .success()。
    let exit_expect = b.expects.iter().find_map(|e| if let Expect::Exit(n) = e { Some(*n) } else { None });
    match exit_expect {
        Some(0) => s.push_str("        .assert().success().get_output().clone();\n"),
        Some(n) => s.push_str(&format!(
            "        .assert().code({n}).get_output().clone();\n")),
        None => s.push_str("        .assert().success().get_output().clone();\n"),
    }

    // 是否有 JSON 断言（命令含 --json 才解析 stdout 为 JSON）。
    let has_json = b.when.contains("--json") && b.expects.iter().any(|e| matches!(e,
        Expect::JsonContains(_) | Expect::JsonField(_, _) | Expect::EveryHas { .. }
        | Expect::ErrorCode(_) | Expect::OmittedHasReason(_)
        | Expect::JsonArrayLen(_, _) | Expect::JsonNumField(_, _)));
    let has_err_code = b.expects.iter().any(|e| matches!(e, Expect::ErrorCode(_)));
    if has_json {
        if exit_expect.map(|n| n != 0).unwrap_or(false) || has_err_code {
            s.push_str("    let actual: Value = serde_json::from_slice(&out.stdout).expect(\"stdout 应为合法 JSON\");\n");
        } else {
            s.push_str("    let actual: Value = serde_json::from_slice(&out.stdout).expect(\"stdout 应为单一合法 JSON\");\n");
        }
    }

    for e in &b.expects {
        match e {
            Expect::Exit(_) => {} // 已在 .code() 处理
            // 05 治理默认化（V2 默认）：`--json` 失败输出为 V2 错误信封，错误 ID 在
            // `errorId` 字段（V1 `ErrorObject` 的 `code` 字段为弃用兼容路径，不在默认断言内）。
            Expect::ErrorCode(code) => {
                s.push_str(&format!(
                    "    assert_eq!(actual[\"errorId\"].as_str().unwrap(), \"{code}\");\n"));
                s.push_str("    assert!(actual[\"message\"].as_str().map_or(false, |m| !m.is_empty()));\n");
            }
            Expect::JsonContains(fields) => {
                for f in fields {
                    if f.contains('.') {
                        // 嵌套：如 audit.compressed / details.partialPacket（断言存在，对象/数组均可）
                        let parts: Vec<&str> = f.split('.').collect();
                        s.push_str(&format!(
                            "    assert!(actual.get(\"{}\").and_then(|v| v.get(\"{}\")).is_some(), \"缺 {f}\");\n",
                            parts[0], parts[1]));
                    } else {
                        s.push_str(&format!(
                            "    assert!(actual.get(\"{f}\").is_some(), \"缺字段 {f}\");\n"));
                    }
                }
            }
            Expect::JsonField(field, value) => {
                s.push_str(&format!(
                    "    assert_eq!(actual[\"{field}\"].as_str().unwrap_or(\"\"), \"{value}\");\n"));
            }
            Expect::JsonArrayLen(field, n) => {
                let idx = render_json_index(field);
                s.push_str(&format!(
                    "    assert_eq!({idx}.as_array().expect(\"字段 {field} 应为数组\").len(), {n});\n"));
            }
            Expect::JsonNumField(field, n) => {
                let idx = render_json_index(field);
                s.push_str(&format!(
                    "    assert_eq!({idx}.as_i64().expect(\"字段 {field} 应为数值\"), {n});\n"));
            }
            Expect::EveryHas { item, field } => {
                s.push_str(&format!(
                    "    for frag in actual[\"{item}\"].as_array().expect(\"{item} 应为数组\") {{\n"));
                s.push_str(&format!(
                    "        assert!(!frag[\"{field}\"].as_array().map_or(false, |a| a.is_empty()), \"{item} 项缺 {field}\");\n"));
                s.push_str("    }\n");
            }
            Expect::OmittedHasReason(reason) => {
                s.push_str("    let omitted = actual[\"overflow\"][\"omitted\"].as_array().expect(\"应有 omitted\");\n");
                s.push_str(&format!(
                    "    assert!(omitted.iter().any(|o| o[\"reason\"].as_str().map_or(false, |r| r == \"{reason}\")));\n"));
            }
            Expect::StdoutContains(sub) => {
                let esc = sub.replace('\\', "\\\\").replace('"', "\\\"").replace('\n', "\\n");
                s.push_str(&format!(
                    "    assert!(String::from_utf8_lossy(&out.stdout).contains(\"{esc}\"));\n"));
            }
        }
    }
    s.push_str("}\n");
    s
}

/// 注册 [[test]] 到 novel-cli Cargo.toml（用 toml_edit 保格式）。
/// 返回本次新注册的 test 名（已存在的不重复注册）。
pub fn register_tests(
    cargo_path: &Path,
    domains: &[(String, Vec<ResolvedBlock>)],
) -> anyhow::Result<Vec<String>> {
    let text = std::fs::read_to_string(cargo_path)?;
    let mut doc = toml_edit::DocumentMut::from_str(&text)?;
    let mut registered = Vec::new();
    let arr = doc["test"].as_array_of_tables_mut()
        .ok_or_else(|| anyhow::anyhow!("Cargo.toml 无 [[test]] 数组"))?;
    let existing_names: Vec<String> = arr.iter()
        .filter_map(|t| t.get("name").and_then(|n| n.as_str()).map(|s| s.to_string()))
        .collect();
    for (domain, _) in domains {
        let test_name = format!("{}_gen", domain);
        if existing_names.iter().any(|n| n == &test_name) {
            continue;
        }
        let mut entry = toml_edit::Table::new();
        entry.insert("name", toml_edit::value(test_name.clone()));
        entry.insert("path", toml_edit::value(format!("../../contracts/cli/generated/{domain}.gen.rs")));
        entry.insert("harness", toml_edit::value(true));
        arr.push(entry);
        registered.push(test_name);
    }
    let new_text = doc.to_string();
    if new_text != text {
        std::fs::write(cargo_path, new_text)?;
    }
    Ok(registered)
}

/// 简易 shell 参数切分（不支持转义引号嵌套，仅覆盖 @codegen when 的简单命令）。
fn shell_split(cmd: &str) -> Vec<String> {
    let mut args = Vec::new();
    let mut cur = String::new();
    let mut in_quote = false;
    let mut quote_char = ' ';
    for c in cmd.chars() {
        match c {
            '"' | '\'' if !in_quote => { in_quote = true; quote_char = c; }
            c if in_quote && c == quote_char => { in_quote = false; }
            ' ' if !in_quote => {
                if !cur.is_empty() { args.push(cur.clone()); cur.clear(); }
            }
            c => cur.push(c),
        }
    }
    if !cur.is_empty() { args.push(cur); }
    args
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::spec_parse::{CodegenBlock, ParsedBlock};
    use crate::ssot;

    /// 从 YAML 片段构造 ParsedBlock（绕过 spec_parse 的文件扫描，单测聚焦解析+渲染）。
    fn block_from_yaml(yaml: &str) -> ParsedBlock {
        let block: CodegenBlock = serde_yaml::from_str(yaml).expect("@codegen yaml 解析失败");
        ParsedBlock {
            spec_rel: "openspec/specs/test/spec.md".to_string(),
            domain: "test".to_string(),
            scenario_title: "单测场景".to_string(),
            block,
        }
    }

    /// 解析 + 渲染一个 block，返回生成的测试函数体字符串。
    fn render_asserts(yaml: &str) -> String {
        let pb = block_from_yaml(yaml);
        let maps = ssot::load_ssot().expect("load_ssot 失败");
        let resolved = resolve_block(&pb, &maps).expect("resolve_block 失败");
        render_one_test(&resolved)
    }

    #[test]
    fn json_array_len_renders_len_assert() {
        let out = render_asserts(
            "id: t_array_len\nfixture: f\nwhen: novel foo --json\nassert:\n  - json_array_len: {settings: 3}\n",
        );
        assert!(
            out.contains(
                "assert_eq!(actual[\"settings\"].as_array().expect(\"字段 settings 应为数组\").len(), 3);"
            ),
            "未找到顶层数组长度断言:\n{out}"
        );
    }

    #[test]
    fn json_array_len_nested_renders_index_chain() {
        let out = render_asserts(
            "id: t_array_nested\nfixture: f\nwhen: novel foo --json\nassert:\n  - json_array_len: {audit.failures: 0}\n",
        );
        assert!(
            out.contains(
                "assert_eq!(actual[\"audit\"][\"failures\"].as_array().expect(\"字段 audit.failures 应为数组\").len(), 0);"
            ),
            "未找到嵌套数组长度断言:\n{out}"
        );
    }

    #[test]
    fn json_num_field_renders_numeric_assert() {
        let out = render_asserts(
            "id: t_num_field\nfixture: f\nwhen: novel foo --json\nassert:\n  - json_num_field: {budget.limit: 60000}\n",
        );
        assert!(
            out.contains(
                "assert_eq!(actual[\"budget\"][\"limit\"].as_i64().expect(\"字段 budget.limit 应为数值\"), 60000);"
            ),
            "未找到嵌套数值断言:\n{out}"
        );
    }
}
